package com.finguard.app;
import com.finguard.config.*;import com.finguard.model.*;import com.finguard.service.*;import com.finguard.util.*;import java.util.*;import java.math.*;import java.time.*;import java.nio.file.*;
public class Main {public static void main(String[] args){System.out.println("========== FINGUARD CLI ==========\nBanking Transaction Risk Analyzer\n==================================");if(!DatabaseConnection.configured()){System.out.println("MySQL is not configured. Create the database: mysql -u root -p < schema.sql\nSet DB_URL, DB_USER and DB_PASSWORD environment variables, then restart. No transaction data was stored.");return;}var sc=new Scanner(System.in);var service=new TransactionService(new RiskAnalysisService(AppConfig.load()));var csv=new CsvService(service);var reports=new ReportService();while(true){menu();try{System.out.print("Choose an option: ");String op=sc.nextLine().trim();switch(op){case "0"->{System.out.println("Goodbye.");return;}case "1"->{System.out.print("Account ID: ");String a=sc.nextLine();System.out.print("Reference: ");String ref=sc.nextLine();System.out.print("Amount: ");BigDecimal amt=new BigDecimal(sc.nextLine());System.out.print("Currency (e.g. INR): ");String curr=sc.nextLine();System.out.print("Type (CREDIT/DEBIT): ");var type=InputValidator.type(sc.nextLine());System.out.print("Merchant/recipient: ");String m=sc.nextLine();System.out.print("Timestamp (yyyy-MM-ddTHH:mm:ss): ");var time=InputValidator.timestamp(sc.nextLine());var t=service.add(new Transaction(null,a,ref,amt,curr,type,m,time,TransactionStatus.COMPLETED,0,RiskLevel.LOW,List.of()));show(t);}
 case "2"->service.all().forEach(Main::show);case "3"->{System.out.print("ID: ");service.id(Long.parseLong(sc.nextLine())).ifPresentOrElse(Main::show,()->System.out.println("Not found"));}case "4"->{System.out.print("Account ID: ");service.account(sc.nextLine()).forEach(Main::show);}case "5"->{System.out.print("From (yyyy-MM-ddTHH:mm:ss): ");var a=InputValidator.timestamp(sc.nextLine());System.out.print("To: ");service.range(a,InputValidator.timestamp(sc.nextLine())).forEach(Main::show);}case "6"->service.all().stream().filter(t->t.riskScore()>0).forEach(Main::show);case "7"->System.out.println(reports.summary(service.all()));case "8"->System.out.println(reports.stats(service.all()));case "9"->service.audit().forEach(System.out::println);case "10"->{System.out.print("Output CSV path: ");csv.export(Path.of(sc.nextLine()));System.out.println("Export complete.");}case "11"->{System.out.print("Input CSV path: ");System.out.println(csv.importFile(Path.of(sc.nextLine())));}case "12"->service.all().stream().filter(t->t.riskLevel()==RiskLevel.HIGH).forEach(Main::show);default->System.out.println("Invalid choice.");}}catch(Exception e){System.out.println("Action failed: "+e.getMessage());org.slf4j.LoggerFactory.getLogger(Main.class).warn("Console action failed",e);}}}
 private static void menu(){System.out.println("\n1. Add New Transaction\n2. View All Transactions\n3. Search Transaction by ID\n4. Search Transactions by Account\n5. Filter Transactions by Date Range\n6. Detect Suspicious Transactions\n7. View Risk Summary Report\n8. View Transaction Statistics\n9. View Audit Logs\n10. Export Transactions to CSV\n11. Import Transactions from CSV\n12. View High-Risk Alerts\n0. Exit");}private static void show(Transaction t){System.out.printf("#%d %s %s %s %s %s %s risk=%d/%s reasons=%s%n",t.id(),t.timestamp(),t.accountId(),t.type(),t.amount(),t.currency(),t.reference(),t.riskScore(),t.riskLevel(),t.reasons());}}